package dev.elpsy.ticket;

import dev.elpsy.ticket.catalog.*;
import dev.elpsy.ticket.catalog.Models.*;
import dev.elpsy.ticket.customer.CustomerService;
import dev.elpsy.ticket.customer.CustomerService.Principal;
import dev.elpsy.ticket.orders.*;
import dev.elpsy.ticket.orders.OrderModels.*;
import dev.elpsy.ticket.orders.OrderModels.Order;
import dev.elpsy.ticket.orders.PaymentModels.*;
import dev.elpsy.ticket.inventory.*;
import dev.elpsy.ticket.admission.AdmissionSettings;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.dao.DataAccessException;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(properties={"ticket.delivery.enabled=false","ticket.admission.enabled=false","ticket.orders.enabled=true","ticket.purchases.enabled=true","ticket.mock-payments.enabled=true","ticket.expiry.enabled=false"})
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class StockOriginIntegrationTest {
 @Autowired CatalogService catalog; @Autowired CustomerService customers; @Autowired OrderService orders;
 @Autowired PaymentService payments; @Autowired PurchaseService purchases; @Autowired StockHoldService holds;
 @Autowired StockProjectionService projections; @Autowired JdbcTemplate db; @Autowired PlatformTransactionManager transactions;
 @Autowired StringRedisTemplate redis; @Autowired ObjectMapper json; @Autowired AdmissionSettings settings;
 String manager="origin-"+UUID.randomUUID(); Set<String> keys=new HashSet<>();
 record Fixture(Principal owner,Event event,Session session,Ticket ticket,UUID create) {}
 record Accepted(Fixture fixture,StockHoldService.Intent intent,UUID purchase,UUID outbox) {}
 @BeforeAll void seed(){assertEquals("ticket_demo",db.queryForObject("SELECT current_database()",String.class));db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),manager,"unused synthetic hash","MANAGER");}
 @AfterEach void cleanup(){redis.delete(keys);keys.clear();}
 Fixture fixture(boolean publish){var issue=customers.register("or-"+UUID.randomUUID().toString().substring(0,30),"合成",UUID.randomUUID().toString());var owner=customers.authenticate(issue.token()).orElseThrow();var e=catalog.createEvent(manager,new EventInput(UUID.randomUUID(),0L,"origin-"+UUID.randomUUID(),"合成","不收款","隔離"));var now=OffsetDateTime.now();var s=catalog.createSession(manager,e.id(),new SessionInput(UUID.randomUUID(),0L,"一般",now.plusDays(2),now.minusHours(1),now.plusHours(1)));var create=UUID.randomUUID();var t=catalog.createTicket(manager,s.id(),new TicketInput(create,0L,"一般",1200,4,4));if(publish)catalog.transition(manager,e.id(),new Transition(UUID.randomUUID(),1L),true);return new Fixture(owner,e,s,t,create);}
 Order place(Fixture f){return orders.place(f.owner(),new Place(UUID.randomUUID(),f.ticket().id(),1,1,1200));}
 Map<String,Object> origin(Fixture f,long revision){return db.queryForMap("SELECT * FROM stock_revision_origin WHERE ticket_id=? AND to_revision=?",f.ticket().id(),revision);}
 int count(Fixture f,String table){return db.queryForObject("SELECT count(*) FROM "+table+" WHERE ticket_id=?",Integer.class,f.ticket().id());}
 int stock(Fixture f,String column){return db.queryForObject("SELECT "+column+" FROM ticket_type WHERE id=?",Integer.class,f.ticket().id());}
 void due(Order o){db.update("WITH stamp AS MATERIALIZED(SELECT clock_timestamp() clock) UPDATE ticket_order SET created_at=clock-interval '11 minutes',expires_at=clock-interval '1 minute' FROM stamp WHERE id=?",o.id());}
 Order start(Fixture f,Order o,String scenario){return payments.start(f.owner(),o.id(),new Pay(UUID.randomUUID(),o.version(),o.totalTwd(),scenario));}
 Accepted accepted(){var f=fixture(true);var p=projections.begin(f.ticket().id(),UUID.randomUUID(),1);keys.add(RedisTicketLedger.epochs(redis,json,settings.namespace()).key(f.ticket().id(),p.generation()));assertEquals("READY",projections.complete(p.requestId()).state());var i=holds.prepare(f.owner(),new Place(UUID.randomUUID(),f.ticket().id(),1,1,1200));assertEquals("HELD",holds.apply(i.id()).state());var purchase=purchases.acceptHold(f.owner(),i.id());return new Accepted(f,i,purchase.id(),db.queryForObject("SELECT id FROM purchase_outbox WHERE purchase_id=?",UUID.class,purchase.id()));}
 Order process(Accepted a){assertTrue(purchases.process(a.outbox()));return orders.detail(a.fixture().owner(),purchases.detail(a.fixture().owner(),a.purchase()).orderId());}
 void fault(Fixture f,Runnable operation){db.execute("ALTER TABLE stock_origin_audit ADD CONSTRAINT origin_test_fault CHECK(ticket_id<>'"+f.ticket().id()+"'::uuid) NOT VALID");try{assertThrows(DataAccessException.class,operation::run);}finally{db.execute("ALTER TABLE stock_origin_audit DROP CONSTRAINT origin_test_fault");}}
 void intact(Fixture f,int revisions,int held,int sold){for(var table:List.of("stock_revision","stock_revision_context","stock_revision_origin","stock_origin_audit"))assertEquals(revisions,count(f,table),table);assertEquals(held,stock(f,"held"));assertEquals(sold,stock(f,"sold"));}

 @Test void createBindsOriginalCommandExactImageAndOneAudit(){var f=fixture(false);var o=origin(f,1);assertEquals("CATALOG_CREATE",o.get("kind"));assertEquals(f.create(),o.get("catalog_request_id"));assertNull(o.get("intent_id"));var c=db.queryForMap("SELECT * FROM stock_revision_context WHERE ticket_id=?",f.ticket().id());assertNull(c.get("from_revision"));assertNull(c.get("old_ticket"));assertEquals(1200,db.queryForObject("SELECT (new_ticket->>'price_twd')::integer FROM stock_revision_context WHERE ticket_id=?",Integer.class,f.ticket().id()));intact(f,1,0,0);}
 @Test void capacityAndQuoteUpdatePreservesExactOldAndNewTerms(){var f=fixture(false);var request=UUID.randomUUID();catalog.updateTicket(manager,f.ticket().id(),new TicketInput(request,1L,"升級",1500,6,3));assertEquals("CATALOG_UPDATE",origin(f,2).get("kind"));assertEquals(request,origin(f,2).get("catalog_request_id"));var c=db.queryForMap("SELECT from_revision,(old_ticket->>'price_twd')::integer price,(old_ticket->>'capacity')::integer capacity,(new_ticket->>'version')::bigint version FROM stock_revision_context WHERE ticket_id=? AND to_revision=2",f.ticket().id());assertEquals(1L,c.get("from_revision"));assertEquals(1200,c.get("price"));assertEquals(4,c.get("capacity"));assertEquals(2L,c.get("version"));intact(f,2,0,0);}
 @Test void nameOnlyVersionAndCommandReplayDoNotInventAvailableDelta(){var f=fixture(false);var in=new TicketInput(UUID.randomUUID(),1L,"改名",1200,4,4);var updated=catalog.updateTicket(manager,f.ticket().id(),in);assertEquals(updated,catalog.updateTicket(manager,f.ticket().id(),in));assertEquals("CATALOG_UPDATE",origin(f,2).get("kind"));assertEquals(4,updated.available());intact(f,2,0,0);}
 @Test void synchronousHoldBindsOriginalOrderWithoutRedisIntent(){var f=fixture(true);var o=place(f);assertEquals("ORDER_HOLD",origin(f,2).get("kind"));assertEquals(o.id(),origin(f,2).get("order_id"));assertEquals("HOLD",origin(f,2).get("order_phase"));assertNull(origin(f,2).get("intent_id"));intact(f,2,1,0);assertEquals("DIRTY",projections.inspect(f.ticket().id()).state());}
 @Test void cancellationReleaseAndReplayKeepOriginalCause(){var f=fixture(true);var o=place(f);var body=new Cancel(UUID.randomUUID(),1);var cancelled=orders.cancel(f.owner(),o.id(),body);assertEquals(cancelled,orders.cancel(f.owner(),o.id(),body));assertEquals("ORDER_RELEASE",origin(f,3).get("kind"));assertEquals(o.id(),origin(f,3).get("order_id"));assertEquals("RELEASE",origin(f,3).get("order_phase"));intact(f,3,0,0);}
 @Test void systemExpiryBindsReleaseRatherThanInventingPayment(){var f=fixture(true);var o=place(f);due(o);assertTrue(orders.expire(o.id()));assertFalse(orders.expire(o.id()));assertEquals("ORDER_RELEASE",origin(f,3).get("kind"));assertEquals("SYSTEM",db.queryForObject("SELECT actor FROM order_inventory_event WHERE order_id=? AND phase='RELEASE'",String.class,o.id()));intact(f,3,0,0);}
 @Test void paymentConversionLinksSuccessfulOriginalEventWithZeroAvailableDelta(){var f=fixture(true);var o=start(f,place(f),"SUCCESS");var body=new Reconcile(UUID.randomUUID());var paid=payments.reconcile(f.owner(),o.id(),o.payment().id(),body);assertEquals(paid,payments.reconcile(f.owner(),o.id(),o.payment().id(),body));var origin=origin(f,3);assertEquals("PAYMENT",origin.get("kind"));assertEquals("SUCCEEDED",db.queryForObject("SELECT decision FROM payment_event WHERE event_id=?",String.class,origin.get("payment_event_id")));assertTrue(db.queryForObject("SELECT (old_ticket->>'capacity')::int-(old_ticket->>'held')::int-(old_ticket->>'sold')::int=(new_ticket->>'capacity')::int-(new_ticket->>'held')::int-(new_ticket->>'sold')::int FROM stock_revision_context WHERE ticket_id=? AND to_revision=3",Boolean.class,f.ticket().id()));intact(f,3,0,1);}
 @Test void declineAndAmountReviewDoNotCreateStockOrigins(){for(var scenario:List.of("DECLINED","SUCCESS")){var f=fixture(true);var o=start(f,place(f),scenario);if(scenario.equals("SUCCESS"))db.update("UPDATE mock_payment_receipt SET amount=1 WHERE attempt_id=?",o.payment().id());payments.reconcile(f.owner(),o.id(),o.payment().id(),new Reconcile(UUID.randomUUID()));intact(f,2,1,0);}}
 @Test void lateSuccessOnlyRecordsExpiryRelease(){var f=fixture(true);var o=start(f,place(f),"SUCCESS");due(o);assertEquals("REVIEW",payments.reconcile(f.owner(),o.id(),o.payment().id(),new Reconcile(UUID.randomUUID())).payment().status());assertEquals("ORDER_RELEASE",origin(f,3).get("kind"));intact(f,3,0,0);}
 @Test void acceptedWorkerLinksOriginalDeferredFormalCommitAndLaterRelease(){var a=accepted();var f=a.fixture();var o=process(a);assertEquals(a.intent().id(),origin(f,2).get("intent_id"));orders.cancel(f.owner(),o.id(),new Cancel(UUID.randomUUID(),o.version()));assertEquals(a.intent().id(),origin(f,3).get("intent_id"));assertEquals("COMMIT",db.queryForObject("SELECT target FROM stock_hold_decision WHERE intent_id=?",String.class,a.intent().id()));intact(f,3,0,0);}
 @Test void acceptedPaymentKeepsOriginalCommitIdentity(){var a=accepted();var f=a.fixture();var o=start(f,process(a),"SUCCESS");payments.reconcile(f.owner(),o.id(),o.payment().id(),new Reconcile(UUID.randomUUID()));assertEquals(a.intent().id(),origin(f,3).get("intent_id"));assertEquals("PAYMENT",origin(f,3).get("kind"));intact(f,3,0,1);}
 @Test void concurrentOriginalWorkerCreatesExactlyOneOrigin()throws Exception{var a=accepted();try(var pool=Executors.newFixedThreadPool(6)){var jobs=new ArrayList<Callable<Boolean>>();for(int i=0;i<6;i++)jobs.add(()->purchases.process(a.outbox()));int processed=0;for(var r:pool.invokeAll(jobs))if(r.get())processed++;assertEquals(1,processed);}intact(a.fixture(),2,1,0);assertEquals(a.intent().id(),origin(a.fixture(),2).get("intent_id"));}
 @Test void auditFailureRollsBackWorkerStockOrderDecisionAndPurchaseThenOriginalRetry(){var a=accepted();var f=a.fixture();fault(f,()->purchases.process(a.outbox()));intact(f,1,0,0);assertEquals("PROCESSING",purchases.detail(f.owner(),a.purchase()).status());assertEquals("READY",projections.inspect(f.ticket().id()).state());assertEquals(0,db.queryForObject("SELECT count(*) FROM ticket_order WHERE customer_id=?",Integer.class,f.owner().id()));assertEquals(0,db.queryForObject("SELECT count(*) FROM stock_hold_decision WHERE intent_id=?",Integer.class,a.intent().id()));process(a);intact(f,2,1,0);}
 @Test void catalogAuditFailureRollsBackTermsVersionCommandAndRevision(){var f=fixture(false);var in=new TicketInput(UUID.randomUUID(),1L,"修改",1500,6,3);fault(f,()->catalog.updateTicket(manager,f.ticket().id(),in));intact(f,1,0,0);assertEquals(1200,stock(f,"price_twd"));assertEquals(0,db.queryForObject("SELECT count(*) FROM catalog_command WHERE request_id=?",Integer.class,in.requestId()));catalog.updateTicket(manager,f.ticket().id(),in);intact(f,2,0,0);}
 @Test void paymentAuditFailureRollsBackConversionEventAndOriginalCommand(){var f=fixture(true);var o=start(f,place(f),"SUCCESS");var body=new Reconcile(UUID.randomUUID());fault(f,()->payments.reconcile(f.owner(),o.id(),o.payment().id(),body));intact(f,2,1,0);assertEquals("PENDING",orders.detail(f.owner(),o.id()).payment().status());assertEquals(0,db.queryForObject("SELECT count(*) FROM payment_event WHERE order_id=?",Integer.class,o.id()));assertEquals(0,db.queryForObject("SELECT count(*) FROM payment_inventory_event WHERE order_id=?",Integer.class,o.id()));payments.reconcile(f.owner(),o.id(),o.payment().id(),body);intact(f,3,0,1);}
 @Test void releaseAuditFailurePreservesHoldThenOriginalCancelRetries(){var f=fixture(true);var o=place(f);var body=new Cancel(UUID.randomUUID(),1);fault(f,()->orders.cancel(f.owner(),o.id(),body));intact(f,2,1,0);assertEquals("PENDING_PAYMENT",orders.detail(f.owner(),o.id()).status());orders.cancel(f.owner(),o.id(),body);intact(f,3,0,0);}
 @Test void twoBusinessMutationsInOneTransactionBindDistinctExactRevisions(){var f=fixture(true);new TransactionTemplate(transactions).execute(tx->{var o=place(f);orders.cancel(f.owner(),o.id(),new Cancel(UUID.randomUUID(),1));return null;});assertEquals("ORDER_HOLD",origin(f,2).get("kind"));assertEquals("ORDER_RELEASE",origin(f,3).get("kind"));assertEquals(1,db.queryForObject("SELECT count(DISTINCT transaction_id) FROM stock_revision_context WHERE ticket_id=? AND to_revision IN(2,3)",Integer.class,f.ticket().id()));intact(f,3,0,0);}
 @Test void directSqlIsUnattributedAndNoopDoesNotInventRevision(){var f=fixture(false);db.update("UPDATE ticket_type SET version=version+1 WHERE id=?",f.ticket().id());assertEquals("UNATTRIBUTED",origin(f,2).get("kind"));db.update("UPDATE ticket_type SET held=held WHERE id=?",f.ticket().id());intact(f,2,0,0);assertEquals("DIRTY",projections.inspect(f.ticket().id()).state());assertThrows(DataAccessException.class,()->db.update("UPDATE ticket_type SET price_twd=1500 WHERE id=?",f.ticket().id()));}
 @Test void deferredUnknownAuditFailureRollsBackJournalAndStock(){var f=fixture(false);fault(f,()->db.update("UPDATE ticket_type SET capacity=capacity+1 WHERE id=?",f.ticket().id()));intact(f,1,0,0);assertEquals(4,stock(f,"capacity"));}
 @Test void originsContextsAuditsAndLinkedOriginalCausesAreImmutable(){var f=fixture(true);var o=start(f,place(f),"SUCCESS");payments.reconcile(f.owner(),o.id(),o.payment().id(),new Reconcile(UUID.randomUUID()));for(var table:List.of("stock_revision_context","stock_revision_origin","stock_origin_audit"))assertThrows(DataAccessException.class,()->db.update("DELETE FROM "+table+" WHERE ticket_id=?",f.ticket().id()));assertThrows(DataAccessException.class,()->db.update("UPDATE catalog_command SET actor_id=actor_id WHERE request_id=?",f.create()));assertThrows(DataAccessException.class,()->db.update("UPDATE order_inventory_event SET delta=delta WHERE order_id=?",o.id()));assertThrows(DataAccessException.class,()->db.update("UPDATE payment_inventory_event SET quantity=quantity WHERE order_id=?",o.id()));assertThrows(DataAccessException.class,()->db.update("UPDATE payment_event SET decision=decision WHERE order_id=?",o.id()));assertThrows(DataAccessException.class,()->db.update("UPDATE ticket_order SET request_id=? WHERE id=?",UUID.randomUUID(),o.id()));intact(f,3,0,1);}
 @Test void migrationBoundaryIsSealedAndHistoricalAttributionIsRejected(){var f=fixture(false);assertThrows(DataAccessException.class,()->db.update("INSERT INTO stock_origin_boundary VALUES(?,1)",f.ticket().id()));assertThrows(DataAccessException.class,()->db.update("INSERT INTO stock_revision_origin(ticket_id,to_revision,kind) VALUES(?,1,'UNATTRIBUTED')",f.ticket().id()));assertThrows(DataAccessException.class,()->db.update("INSERT INTO stock_revision_origin(ticket_id,to_revision,kind) VALUES(?,1,'ORDER_HOLD')",f.ticket().id()));intact(f,1,0,0);}
 @Test void creationAuditFailureCannotLeaveOrphanTicketJournalOrCommand(){var f=fixture(false);var body=new TicketInput(UUID.randomUUID(),0L,"新票",1000,4,4);db.execute("ALTER TABLE stock_origin_audit ADD CONSTRAINT origin_create_fault CHECK(to_revision<>1) NOT VALID");try{assertThrows(DataAccessException.class,()->catalog.createTicket(manager,f.session().id(),body));assertEquals(1,db.queryForObject("SELECT count(*) FROM ticket_type WHERE session_id=?",Integer.class,f.session().id()));assertEquals(0,db.queryForObject("SELECT count(*) FROM catalog_command WHERE request_id=?",Integer.class,body.requestId()));}finally{db.execute("ALTER TABLE stock_origin_audit DROP CONSTRAINT origin_create_fault");}var t=catalog.createTicket(manager,f.session().id(),body);assertEquals("CATALOG_CREATE",db.queryForObject("SELECT kind FROM stock_revision_origin WHERE ticket_id=?",String.class,t.id()));}
 @Test void contextWriterFailureRollsBackFormalHoldBeforeOriginExists(){var f=fixture(true);var body=new Place(UUID.randomUUID(),f.ticket().id(),1,1,1200);db.execute("ALTER TABLE stock_revision_context ADD CONSTRAINT origin_context_fault CHECK(ticket_id<>'"+f.ticket().id()+"'::uuid) NOT VALID");try{assertThrows(DataAccessException.class,()->orders.place(f.owner(),body));intact(f,1,0,0);assertEquals(0,db.queryForObject("SELECT count(*) FROM ticket_order WHERE customer_id=?",Integer.class,f.owner().id()));}finally{db.execute("ALTER TABLE stock_revision_context DROP CONSTRAINT origin_context_fault");}orders.place(f.owner(),body);intact(f,2,1,0);}
 @Test void multipleUnattributedRevisionsAreIndividuallyFinalizedAtCommit(){var f=fixture(false);new TransactionTemplate(transactions).execute(tx->{db.update("UPDATE ticket_type SET capacity=capacity+1 WHERE id=?",f.ticket().id());db.update("UPDATE ticket_type SET version=version+1 WHERE id=?",f.ticket().id());return null;});assertEquals("UNATTRIBUTED",origin(f,2).get("kind"));assertEquals("UNATTRIBUTED",origin(f,3).get("kind"));intact(f,3,0,0);}
 @Test void nativeTransactionCastRetainsLowXidAcrossEpochBoundary(){assertTrue(db.queryForObject("SELECT '4294967297'::xid8::xid='1'::xid AND '4294967297'::xid8::xid<>'2'::xid AND pg_current_xact_id()::xid=txid_current()::text::xid",Boolean.class));}

}
